package jadx.gui.ui.dialog;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;

import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.SwingConstants;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import jadx.api.data.CommentStyle;
import jadx.api.data.ICodeComment;
import jadx.api.data.impl.JadxCodeComment;
import jadx.api.data.impl.JadxCodeData;
import jadx.gui.settings.JadxProject;
import jadx.gui.ui.codearea.CodeArea;
import jadx.gui.utils.NLS;
import jadx.gui.utils.TextStandardActions;

public class CommentDialog extends CommonDialog {
	private static final long serialVersionUID = -1865682124935757528L;

	private static final Logger LOG = LoggerFactory.getLogger(CommentDialog.class);

	public static void show(CodeArea codeArea, ICodeComment comment, boolean updateComment) {
		CommentDialog dialog = new CommentDialog(codeArea, comment, updateComment);
		dialog.setVisible(true);
	}

	public static void updateCommentsData(CodeArea codeArea, Consumer<List<ICodeComment>> updater) {
		try {
			JadxProject project = codeArea.getProject();
			JadxCodeData codeData = project.getCodeData();
			if (codeData == null) {
				codeData = new JadxCodeData();
			}
			List<ICodeComment> list = new ArrayList<>(codeData.getComments());
			updater.accept(list);
			Collections.sort(list);
			codeData.setComments(list);
			project.setCodeData(codeData);
			codeArea.getMainWindow().getWrapper().reloadCodeData();
		} catch (Exception e) {
			LOG.error("Comment action failed", e);
		}
		try {
			// refresh code in a background thread to avoid blocking the ui
			codeArea.backgroundRefreshClass();
		} catch (Exception e) {
			LOG.error("Failed to reload code", e);
		}
	}

	private final transient CodeArea codeArea;
	private final transient ICodeComment comment;
	private final transient boolean updateComment;

	private transient JTextArea commentArea;
	private transient JComboBox<CommentStyle> styleCombo;

	public CommentDialog(CodeArea codeArea, ICodeComment comment, boolean updateComment) {
		super(codeArea.getMainWindow());
		this.codeArea = codeArea;
		this.comment = comment;
		this.updateComment = updateComment;
		initUI();
	}

	private void apply() {
		String newCommentStr = commentArea.getText().trim();
		if (newCommentStr.isEmpty()) {
			if (updateComment) {
				remove();
			} else {
				cancel();
			}
			return;
		}
		CommentStyle style = (CommentStyle) styleCombo.getSelectedItem();
		ICodeComment newComment = new JadxCodeComment(comment.getNodeRef(), comment.getCodeRef(), newCommentStr, style);
		if (updateComment) {
			updateCommentsData(codeArea, list -> {
				list.remove(comment);
				list.add(newComment);
			});
		} else {
			updateCommentsData(codeArea, list -> list.add(newComment));
		}
		dispose();
	}

	private void remove() {
		updateCommentsData(codeArea, list -> list.removeIf(c -> c == comment));
		dispose();
	}

	private void cancel() {
		dispose();
	}

	private void initUI() {
		commentArea = new JTextArea();
		TextStandardActions.attach(commentArea);
		commentArea.setEditable(true);
		commentArea.setFont(mainWindow.getSettings().getCodeFont());
		commentArea.setAlignmentX(Component.LEFT_ALIGNMENT);

		commentArea.addKeyListener(new KeyAdapter() {
			@Override
			public void keyPressed(KeyEvent e) {
				switch (e.getKeyCode()) {
					case KeyEvent.VK_ENTER:
						if (e.isShiftDown() || e.isControlDown()) {
							commentArea.insert("\n", commentArea.getCaretPosition());
						} else {
							apply();
						}
						break;

					case KeyEvent.VK_ESCAPE:
						cancel();
						break;
				}
			}
		});
		if (updateComment) {
			commentArea.setText(comment.getComment());
		}

		JScrollPane textAreaScrollPane = new JScrollPane(commentArea);
		textAreaScrollPane.setAlignmentX(LEFT_ALIGNMENT);

		styleCombo = new JComboBox<>(CommentStyle.values());
		styleCombo.setSelectedItem(comment.getStyle());

		JLabel commentLabel = new JLabel(NLS.str("comment_dialog.label"), SwingConstants.LEFT);
		JLabel styleLabel = new JLabel(NLS.str("comment_dialog.style"), SwingConstants.LEFT);
		JLabel usageLabel = new JLabel(NLS.str("comment_dialog.usage"), SwingConstants.LEFT);

		JPanel inputPanel = new JPanel();
		inputPanel.setLayout(new BoxLayout(inputPanel, BoxLayout.PAGE_AXIS));
		inputPanel.add(commentLabel);
		inputPanel.add(Box.createRigidArea(new Dimension(0, 5)));
		inputPanel.add(textAreaScrollPane);
		inputPanel.add(Box.createRigidArea(new Dimension(0, 5)));
		inputPanel.add(usageLabel);

		JPanel stylePanel = new JPanel();
		stylePanel.setLayout(new BoxLayout(stylePanel, BoxLayout.LINE_AXIS));
		stylePanel.setAlignmentX(LEFT_ALIGNMENT);
		stylePanel.add(styleLabel);
		stylePanel.add(Box.createRigidArea(new Dimension(5, 0)));
		stylePanel.add(styleCombo);

		JPanel mainPanel = new JPanel(new BorderLayout(10, 10));
		mainPanel.add(inputPanel, BorderLayout.CENTER);
		mainPanel.add(stylePanel, BorderLayout.PAGE_END);
		mainPanel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JPanel buttonPane = initButtonsPanel();

		Container contentPane = getContentPane();
		contentPane.add(mainPanel, BorderLayout.CENTER);
		contentPane.add(buttonPane, BorderLayout.PAGE_END);

		if (updateComment) {
			setTitle(NLS.str("comment_dialog.title.update"));
		} else {
			setTitle(NLS.str("comment_dialog.title.add"));
		}
		commonWindowInit();
	}

	protected JPanel initButtonsPanel() {
		JButton cancelButton = new JButton(NLS.str("common_dialog.cancel"));
		cancelButton.addActionListener(event -> cancel());

		String applyStr = updateComment ? NLS.str("common_dialog.update") : NLS.str("common_dialog.add");
		JButton renameBtn = new JButton(applyStr);
		renameBtn.addActionListener(event -> apply());
		getRootPane().setDefaultButton(renameBtn);

		JButton removeBtn;
		if (updateComment) {
			removeBtn = new JButton(NLS.str("common_dialog.remove"));
			removeBtn.addActionListener(event -> remove());
		} else {
			removeBtn = null;
		}

		JPanel buttonPane = new JPanel();
		buttonPane.setLayout(new BoxLayout(buttonPane, BoxLayout.LINE_AXIS));
		buttonPane.setBorder(BorderFactory.createEmptyBorder(0, 10, 10, 10));
		buttonPane.add(Box.createRigidArea(new Dimension(5, 0)));
		buttonPane.add(Box.createHorizontalGlue());
		buttonPane.add(renameBtn);
		if (removeBtn != null) {
			buttonPane.add(Box.createRigidArea(new Dimension(10, 0)));
			buttonPane.add(removeBtn);
		}
		buttonPane.add(Box.createRigidArea(new Dimension(10, 0)));
		buttonPane.add(cancelButton);
		return buttonPane;
	}
}

package jadx.core.deobf;

import java.io.File;
import java.io.IOException;
import java.nio.charset.Charset;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import jadx.api.JadxArgs;
import jadx.api.args.GeneratedRenamesMappingFileMode;
import jadx.api.deobf.IAliasProvider;
import jadx.api.deobf.impl.AlwaysRename;
import jadx.core.dex.info.ClassInfo;
import jadx.core.dex.info.FieldInfo;
import jadx.core.dex.info.MethodInfo;
import jadx.core.dex.nodes.ClassNode;
import jadx.core.dex.nodes.FieldNode;
import jadx.core.dex.nodes.MethodNode;
import jadx.core.dex.nodes.PackageNode;
import jadx.core.dex.nodes.RootNode;
import jadx.core.utils.files.FileUtils;

import static java.nio.charset.StandardCharsets.UTF_8;

public class DeobfPresets {
	private static final Logger LOG = LoggerFactory.getLogger(DeobfPresets.class);

	private static final Charset MAP_FILE_CHARSET = UTF_8;

	private final Path deobfMapFile;

	private final Map<String, String> pkgPresetMap = new HashMap<>();
	private final Map<String, String> clsPresetMap = new HashMap<>();
	private final Map<String, String> fldPresetMap = new HashMap<>();
	private final Map<String, String> mthPresetMap = new HashMap<>();

	public static DeobfPresets build(RootNode root) {
		Path deobfMapPath = getPathDeobfMapPath(root);
		if (root.getArgs().getGeneratedRenamesMappingFileMode() != GeneratedRenamesMappingFileMode.IGNORE) {
			LOG.debug("Deobfuscation map file set to: {}", deobfMapPath);
		}
		return new DeobfPresets(deobfMapPath);
	}

	private static Path getPathDeobfMapPath(RootNode root) {
		JadxArgs jadxArgs = root.getArgs();
		File deobfMapFile = jadxArgs.getGeneratedRenamesMappingFile();
		if (deobfMapFile != null) {
			return deobfMapFile.toPath();
		}
		Path inputFilePath = jadxArgs.getInputFiles().get(0).toPath().toAbsolutePath();
		String baseName = FileUtils.getPathBaseName(inputFilePath);
		return inputFilePath.getParent().resolve(baseName + ".jobf");
	}

	private DeobfPresets(Path deobfMapFile) {
		this.deobfMapFile = deobfMapFile;
	}

	/**
	 * Loads deobfuscator presets
	 */
	public boolean load() {
		if (!Files.exists(deobfMapFile)) {
			return false;
		}
		LOG.info("Loading obfuscation map from: {}", deobfMapFile.toAbsolutePath());
		try {
			List<String> lines = Files.readAllLines(deobfMapFile, MAP_FILE_CHARSET);
			for (String l : lines) {
				l = l.trim();
				if (l.isEmpty() || l.startsWith("#")) {
					continue;
				}
				String[] va = splitAndTrim(l);
				if (va.length != 2) {
					continue;
				}
				String origName = va[0];
				String alias = va[1];
				switch (l.charAt(0)) {
					case 'p':
						pkgPresetMap.put(origName, alias);
						break;
					case 'c':
						clsPresetMap.put(origName, alias);
						break;
					case 'f':
						fldPresetMap.put(origName, alias);
						break;
					case 'm':
						mthPresetMap.put(origName, alias);
						break;
					case 'v':
						// deprecated
						break;
				}
			}
			return true;
		} catch (Exception e) {
			LOG.error("Failed to load deobfuscation map file '{}'", deobfMapFile.toAbsolutePath(), e);
			return false;
		}
	}

	private static String[] splitAndTrim(String str) {
		String[] v = str.substring(2).split("=");
		for (int i = 0; i < v.length; i++) {
			v[i] = v[i].trim();
		}
		return v;
	}

	public void save() throws IOException {
		List<String> list = new ArrayList<>();
		for (Map.Entry<String, String> pkgEntry : pkgPresetMap.entrySet()) {
			list.add("p " + pkgEntry.getKey() + " = " + pkgEntry.getValue());
		}
		for (Map.Entry<String, String> clsEntry : clsPresetMap.entrySet()) {
			list.add("c " + clsEntry.getKey() + " = " + clsEntry.getValue());
		}
		for (Map.Entry<String, String> fldEntry : fldPresetMap.entrySet()) {
			list.add("f " + fldEntry.getKey() + " = " + fldEntry.getValue());
		}
		for (Map.Entry<String, String> mthEntry : mthPresetMap.entrySet()) {
			list.add("m " + mthEntry.getKey() + " = " + mthEntry.getValue());
		}
		Collections.sort(list);
		if (list.isEmpty()) {
			if (LOG.isDebugEnabled()) {
				LOG.debug("Deobfuscation map is empty, not saving it");
			}
			return;
		}
		Files.write(deobfMapFile, list, MAP_FILE_CHARSET,
				StandardOpenOption.WRITE, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
		LOG.info("Deobfuscation map file saved as: {}", deobfMapFile);
	}

	public void fill(RootNode root) {
		for (PackageNode pkg : root.getPackages()) {
			if (pkg.isLeaf()) { // ignore middle packages
				if (pkg.hasParentAlias()) {
					pkgPresetMap.put(pkg.getPkgInfo().getFullName(), pkg.getAliasPkgInfo().getFullName());
				} else if (pkg.hasAlias()) {
					pkgPresetMap.put(pkg.getPkgInfo().getFullName(), pkg.getAliasPkgInfo().getName());
				}
			}
		}
		for (ClassNode cls : root.getClasses()) {
			ClassInfo classInfo = cls.getClassInfo();
			if (classInfo.hasAlias()) {
				clsPresetMap.put(classInfo.makeRawFullName(), classInfo.getAliasShortName());
			}
			for (FieldNode fld : cls.getFields()) {
				FieldInfo fieldInfo = fld.getFieldInfo();
				if (fieldInfo.hasAlias()) {
					fldPresetMap.put(fieldInfo.getRawFullId(), fld.getAlias());
				}
			}
			for (MethodNode mth : cls.getMethods()) {
				MethodInfo methodInfo = mth.getMethodInfo();
				if (methodInfo.hasAlias()) {
					mthPresetMap.put(methodInfo.getRawFullId(), methodInfo.getAlias());
				}
			}
		}
	}

	public void apply(RootNode root) {
		DeobfuscatorVisitor.process(root,
				AlwaysRename.INSTANCE,
				new IAliasProvider() {
					@Override
					public String forPackage(PackageNode pkg) {
						return pkgPresetMap.get(pkg.getPkgInfo().getFullName());
					}

					@Override
					public String forClass(ClassNode cls) {
						return getForCls(cls.getClassInfo());
					}

					@Override
					public String forField(FieldNode fld) {
						return getForFld(fld.getFieldInfo());
					}

					@Override
					public String forMethod(MethodNode mth) {
						return getForMth(mth.getMethodInfo());
					}
				});
	}

	public void initIndexes(IAliasProvider aliasProvider) {
		aliasProvider.initIndexes(pkgPresetMap.size(), clsPresetMap.size(), fldPresetMap.size(), mthPresetMap.size());
	}

	public String getForCls(ClassInfo cls) {
		if (clsPresetMap.isEmpty()) {
			return null;
		}
		return clsPresetMap.get(cls.makeRawFullName());
	}

	public String getForFld(FieldInfo fld) {
		if (fldPresetMap.isEmpty()) {
			return null;
		}
		return fldPresetMap.get(fld.getRawFullId());
	}

	public String getForMth(MethodInfo mth) {
		if (mthPresetMap.isEmpty()) {
			return null;
		}
		return mthPresetMap.get(mth.getRawFullId());
	}

	public void clear() {
		pkgPresetMap.clear();
		clsPresetMap.clear();
		fldPresetMap.clear();
		mthPresetMap.clear();
	}

	public Path getDeobfMapFile() {
		return deobfMapFile;
	}

	public Map<String, String> getPkgPresetMap() {
		return pkgPresetMap;
	}

	public Map<String, String> getClsPresetMap() {
		return clsPresetMap;
	}

	public Map<String, String> getFldPresetMap() {
		return fldPresetMap;
	}

	public Map<String, String> getMthPresetMap() {
		return mthPresetMap;
	}
}

package jadx.core.utils;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import org.jetbrains.annotations.Nullable;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import jadx.core.Consts;
import jadx.core.dex.attributes.AType;
import jadx.core.dex.attributes.IAttributeNode;
import jadx.core.dex.attributes.nodes.JadxError;
import jadx.core.dex.nodes.IDexNode;
import jadx.core.dex.nodes.MethodNode;
import jadx.core.utils.exceptions.JadxOverflowException;

public class ErrorsCounter {
	private static final Logger LOG = LoggerFactory.getLogger(ErrorsCounter.class);
	private static final boolean PRINT_MTH_SIZE = Consts.DEBUG;

	private final Set<IAttributeNode> errorNodes = new HashSet<>();
	private int errorsCount;
	private final Set<IAttributeNode> warnNodes = new HashSet<>();
	private int warnsCount;

	public static <N extends IDexNode & IAttributeNode> String error(N node, String warnMsg, Throwable th) {
		return node.root().getErrorsCounter().addError(node, warnMsg, th);
	}

	public static <N extends IDexNode & IAttributeNode> void warning(N node, String warnMsg) {
		node.root().getErrorsCounter().addWarning(node, warnMsg);
	}

	public static String formatMsg(IDexNode node, String msg) {
		return msg + " in " + node.typeName() + ": " + node + ", file: " + node.getInputFileName();
	}

	private synchronized <N extends IDexNode & IAttributeNode> String addError(N node, String error, @Nullable Throwable e) {
		errorNodes.add(node);
		errorsCount++;

		String msg = formatMsg(node, error);
		if (PRINT_MTH_SIZE && node instanceof MethodNode) {
			String mthSize = "[" + ((MethodNode) node).getInsnsCount() + "] ";
			msg = mthSize + msg;
			error = mthSize + error;
		}
		if (e == null) {
			LOG.error(msg);
		} else if (e instanceof StackOverflowError) {
			LOG.error("{}, error: StackOverflowError", msg);
		} else if (e instanceof JadxOverflowException) {
			// don't print full stack trace
			String details = e.getMessage();
			e = new JadxOverflowException(details);
			if (details == null || details.isEmpty()) {
				LOG.error("{}", msg);
			} else {
				LOG.error("{}, details: {}", msg, details);
			}
		} else {
			LOG.error(msg, e);
		}
		node.addAttr(AType.JADX_ERROR, new JadxError(error, e));
		return msg;
	}

	private synchronized <N extends IDexNode & IAttributeNode> void addWarning(N node, String warn) {
		warnNodes.add(node);
		warnsCount++;
		LOG.warn(formatMsg(node, warn));
	}

	public void printReport() {
		if (getErrorCount() > 0) {
			LOG.error("{} errors occurred in following nodes:", getErrorCount());
			List<String> errors = new ArrayList<>(errorNodes.size());
			for (IAttributeNode node : errorNodes) {
				String nodeName = node.getClass().getSimpleName().replace("Node", "");
				errors.add(nodeName + ": " + node);
			}
			Collections.sort(errors);
			for (String err : errors) {
				LOG.error("  {}", err);
			}
		}
		if (getWarnsCount() > 0) {
			LOG.warn("{} warnings in {} nodes", getWarnsCount(), warnNodes.size());
		}
	}

	public int getErrorCount() {
		return errorsCount;
	}

	public int getWarnsCount() {
		return warnsCount;
	}

	public Set<IAttributeNode> getErrorNodes() {
		return errorNodes;
	}

	public Set<IAttributeNode> getWarnNodes() {
		return warnNodes;
	}
}

package jadx.core.utils;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

import org.jetbrains.annotations.NotNull;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import jadx.api.IDecompileScheduler;
import jadx.api.JavaClass;
import jadx.core.utils.exceptions.JadxRuntimeException;

public class DecompilerScheduler implements IDecompileScheduler {
	private static final Logger LOG = LoggerFactory.getLogger(DecompilerScheduler.class);

	private static final int MERGED_BATCH_SIZE = 16;
	private static final boolean DEBUG_BATCHES = false;

	@Override
	public List<List<JavaClass>> buildBatches(List<JavaClass> classes) {
		try {
			long start = System.currentTimeMillis();
			List<List<JavaClass>> result = internalBatches(classes);
			if (LOG.isDebugEnabled()) {
				LOG.debug("Build decompilation batches in {}ms for {} classes",
						System.currentTimeMillis() - start, classes.size());
			}
			if (DEBUG_BATCHES) {
				check(result, classes);
			}
			return result;
		} catch (StackOverflowError | BootstrapMethodError e) {
			LOG.warn("Stack overflow while building decompile batches, continue with fallback");
		} catch (Exception e) {
			LOG.warn("Build batches failed (continue with fallback)", e);
		}
		return buildFallback(classes);
	}

	/**
	 * Put classes with many dependencies at the end.
	 * Build batches for dependencies of single class to avoid locking from another thread.
	 */
	public List<List<JavaClass>> internalBatches(List<JavaClass> classes) {
		List<DepInfo> deps = sumDependencies(classes);
		Set<JavaClass> added = new HashSet<>(classes.size());
		Comparator<JavaClass> cmpDepSize = Comparator.comparingInt(JavaClass::getTotalDepsCount);
		List<List<JavaClass>> result = new ArrayList<>();
		List<JavaClass> mergedBatch = new ArrayList<>(MERGED_BATCH_SIZE);
		for (DepInfo depInfo : deps) {
			JavaClass cls = depInfo.getCls();
			if (!added.add(cls)) {
				continue;
			}
			int depsSize = cls.getTotalDepsCount();
			if (depsSize == 0) {
				// add classes without dependencies in merged batch
				mergedBatch.add(cls);
				if (mergedBatch.size() >= MERGED_BATCH_SIZE) {
					result.add(mergedBatch);
					mergedBatch = new ArrayList<>(MERGED_BATCH_SIZE);
				}
			} else {
				List<JavaClass> batch = new ArrayList<>();
				for (JavaClass dep : cls.getDependencies()) {
					JavaClass topDep = dep.getTopParentClass();
					if (!added.contains(topDep)) {
						batch.add(topDep);
						added.add(topDep);
					}
				}
				batch.sort(cmpDepSize);
				batch.add(cls);
				result.add(Utils.lockList(batch));
			}
		}
		if (!mergedBatch.isEmpty()) {
			result.add(mergedBatch);
		}
		if (DEBUG_BATCHES) {
			dumpBatchesStats(classes, result, deps);
		}
		return result;
	}

	private static List<DepInfo> sumDependencies(List<JavaClass> classes) {
		List<DepInfo> deps = new ArrayList<>(classes.size());
		for (JavaClass cls : classes) {
			int count = 0;
			for (JavaClass dep : cls.getDependencies()) {
				count += 1 + dep.getTotalDepsCount();
			}
			deps.add(new DepInfo(cls, count));
		}
		Collections.sort(deps);
		return deps;
	}

	private static final class DepInfo implements Comparable<DepInfo> {
		private final JavaClass cls;
		private final int depsCount;

		private DepInfo(JavaClass cls, int depsCount) {
			this.cls = cls;
			this.depsCount = depsCount;
		}

		public JavaClass getCls() {
			return cls;
		}

		public int getDepsCount() {
			return depsCount;
		}

		@Override
		public int compareTo(@NotNull DecompilerScheduler.DepInfo o) {
			int deps = Integer.compare(depsCount, o.depsCount);
			if (deps == 0) {
				return cls.getClassNode().compareTo(o.cls.getClassNode());
			}
			return deps;
		}

		@Override
		public String toString() {
			return cls + ":" + depsCount;
		}
	}

	private static List<List<JavaClass>> buildFallback(List<JavaClass> classes) {
		return classes.stream()
				.sorted(Comparator.comparingInt(c -> c.getClassNode().getTotalDepsCount()))
				.map(Collections::singletonList)
				.collect(Collectors.toList());
	}

	private void dumpBatchesStats(List<JavaClass> classes, List<List<JavaClass>> result, List<DepInfo> deps) {
		int clsInBatches = result.stream().mapToInt(List::size).sum();
		double avg = result.stream().mapToInt(List::size).average().orElse(-1);
		int maxSingleDeps = classes.stream().mapToInt(JavaClass::getTotalDepsCount).max().orElse(-1);
		int maxSubDeps = deps.stream().mapToInt(DepInfo::getDepsCount).max().orElse(-1);
		LOG.info("Batches stats:"
				+ "\n input classes: " + classes.size()
				+ ",\n classes in batches: " + clsInBatches
				+ ",\n batches: " + result.size()
				+ ",\n average batch size: " + String.format("%.2f", avg)
				+ ",\n max single deps count: " + maxSingleDeps
				+ ",\n max sub deps count: " + maxSubDeps);
	}

	private static void check(List<List<JavaClass>> result, List<JavaClass> classes) {
		int classInBatches = result.stream().mapToInt(List::size).sum();
		if (classes.size() != classInBatches) {
			throw new JadxRuntimeException(
					"Incorrect number of classes in result batch: " + classInBatches + ", expected: " + classes.size());
		}
	}
}

package jadx.core.xmlgen;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import jadx.api.ICodeInfo;
import jadx.api.ICodeWriter;
import jadx.api.JadxArgs;
import jadx.api.impl.SimpleCodeWriter;
import jadx.core.utils.StringUtils;
import jadx.core.xmlgen.entry.ProtoValue;
import jadx.core.xmlgen.entry.RawNamedValue;
import jadx.core.xmlgen.entry.ResourceEntry;
import jadx.core.xmlgen.entry.ValuesParser;

import static jadx.core.xmlgen.ParserConstants.PLURALS_MAP;
import static jadx.core.xmlgen.ParserConstants.TYPE_REFERENCE;

public class ResXmlGen {

	/**
	 * Skip only file based resource type
	 */
	private static final Set<String> SKIP_RES_TYPES = new HashSet<>(Arrays.asList(
			"anim",
			"animator",
			"font",
			"id", // skip id type, it is usually auto generated when used this syntax "@+id/my_id"
			"interpolator",
			"layout",
			"menu",
			"mipmap",
			"navigation",
			"raw",
			"transition",
			"xml"));

	private final ResourceStorage resStorage;
	private final ValuesParser vp;
	private final ManifestAttributes manifestAttributes;

	public ResXmlGen(ResourceStorage resStorage, ValuesParser vp, ManifestAttributes manifestAttributes) {
		this.resStorage = resStorage;
		this.vp = vp;
		this.manifestAttributes = manifestAttributes;
	}

	public List<ResContainer> makeResourcesXml(JadxArgs args) {
		Map<String, ICodeWriter> contMap = new HashMap<>();
		for (ResourceEntry ri : resStorage.getResources()) {
			if (SKIP_RES_TYPES.contains(ri.getTypeName())) {
				continue;
			}
			String fn = getFileName(ri);
			ICodeWriter cw = contMap.get(fn);
			if (cw == null) {
				cw = new SimpleCodeWriter(args);
				cw.add("<?xml version=\"1.0\" encoding=\"utf-8\"?>");
				cw.startLine("<resources>");
				cw.incIndent();
				contMap.put(fn, cw);
			}
			addValue(cw, ri);
		}

		List<ResContainer> files = new ArrayList<>(contMap.size());
		for (Map.Entry<String, ICodeWriter> entry : contMap.entrySet()) {
			String fileName = entry.getKey();
			ICodeWriter content = entry.getValue();
			content.decIndent();
			content.startLine("</resources>");
			ICodeInfo codeInfo = content.finish();
			files.add(ResContainer.textResource(fileName, codeInfo));
		}
		Collections.sort(files);
		return files;
	}

	private void addValue(ICodeWriter cw, ResourceEntry ri) {
		if (ri.getProtoValue() != null) {
			ProtoValue protoValue = ri.getProtoValue();
			if (protoValue.getValue() != null && protoValue.getNamedValues() == null) {
				addSimpleValue(cw, ri.getTypeName(), ri.getTypeName(), "name", ri.getKeyName(), protoValue.getValue());
			} else {
				cw.startLine();
				cw.add('<').add(ri.getTypeName()).add(' ');
				String itemTag = "item";
				cw.add("name=\"").add(ri.getKeyName()).add('\"');
				if (ri.getTypeName().equals("attr") && protoValue.getValue() != null) {
					cw.add(" format=\"").add(protoValue.getValue()).add('\"');
				}
				if (protoValue.getParent() != null) {
					cw.add(" parent=\"").add(protoValue.getParent()).add('\"');
				}
				cw.add(">");

				cw.incIndent();
				for (ProtoValue value : protoValue.getNamedValues()) {
					addProtoItem(cw, itemTag, ri.getTypeName(), value);
				}
				cw.decIndent();
				cw.startLine().add("</").add(ri.getTypeName()).add('>');
			}
		} else if (ri.getSimpleValue() != null) {
			String valueStr = vp.decodeValue(ri.getSimpleValue());
			addSimpleValue(cw, ri.getTypeName(), ri.getTypeName(), "name", ri.getKeyName(), valueStr);
		} else {
			boolean skipNamedValues = false;
			cw.startLine();
			cw.add('<').add(ri.getTypeName()).add(" name=\"");
			String itemTag = "item";
			if (ri.getTypeName().equals("attr") && !ri.getNamedValues().isEmpty()) {
				cw.add(ri.getKeyName());
				int type = ri.getNamedValues().get(0).getRawValue().getData();
				if ((type & ValuesParser.ATTR_TYPE_ENUM) != 0) {
					itemTag = "enum";
				} else if ((type & ValuesParser.ATTR_TYPE_FLAGS) != 0) {
					itemTag = "flag";
				}
				String formatValue = XmlGenUtils.getAttrTypeAsString(type);
				if (formatValue != null) {
					cw.add("\" format=\"").add(formatValue);
				}
				if (ri.getNamedValues().size() > 1) {
					for (RawNamedValue rv : ri.getNamedValues()) {
						if (rv.getNameRef() == ParserConstants.ATTR_MIN) {
							cw.add("\" min=\"").add(String.valueOf(rv.getRawValue().getData()));
							skipNamedValues = true;
						}
					}
				}
			} else {
				cw.add(ri.getKeyName());
			}
			if (ri.getTypeName().equals("style") || ri.getParentRef() != 0) {
				cw.add("\" parent=\"");
				if (ri.getParentRef() != 0) {
					String parent = vp.decodeValue(TYPE_REFERENCE, ri.getParentRef());
					cw.add(parent);
				}
			}
			cw.add("\">");

			if (!skipNamedValues) {
				cw.incIndent();
				for (RawNamedValue value : ri.getNamedValues()) {
					addItem(cw, itemTag, ri.getTypeName(), value);
				}
				cw.decIndent();
			}
			cw.startLine().add("</").add(ri.getTypeName()).add('>');
		}
	}

	private void addProtoItem(ICodeWriter cw, String itemTag, String typeName, ProtoValue protoValue) {
		String name = protoValue.getName();
		String value = protoValue.getValue();
		switch (typeName) {
			case "attr":
				if (name != null) {
					addSimpleValue(cw, typeName, itemTag, name, value, "");
				}
				break;
			case "style":
				if (name != null) {
					addSimpleValue(cw, typeName, itemTag, name, "", value);
				}
				break;
			case "plurals":
				addSimpleValue(cw, typeName, itemTag, "quantity", name, value);
				break;
			default:
				addSimpleValue(cw, typeName, itemTag, null, null, value);
				break;
		}
	}

	private void addItem(ICodeWriter cw, String itemTag, String typeName, RawNamedValue value) {
		String nameStr = vp.decodeNameRef(value.getNameRef());
		String valueStr = vp.decodeValue(value.getRawValue());
		int dataType = value.getRawValue().getDataType();

		if (!typeName.equals("attr")) {
			if (dataType == ParserConstants.TYPE_REFERENCE && (valueStr == null || valueStr.equals("0"))) {
				valueStr = "@null";
			}
			if (dataType == ParserConstants.TYPE_INT_DEC && nameStr != null) {
				try {
					int intVal = Integer.parseInt(valueStr);
					String newVal = manifestAttributes.decode(nameStr.replace("android:", "").replace("attr.", ""), intVal);
					if (newVal != null) {
						valueStr = newVal;
					}
				} catch (NumberFormatException e) {
					// ignore
				}
			}
			if (dataType == ParserConstants.TYPE_INT_HEX && nameStr != null) {
				try {
					int intVal = Integer.decode(valueStr);
					String newVal = manifestAttributes.decode(nameStr.replace("android:", "").replace("attr.", ""), intVal);
					if (newVal != null) {
						valueStr = newVal;
					}
				} catch (NumberFormatException e) {
					// ignore
				}
			}
		}
		switch (typeName) {
			case "attr":
				if (nameStr != null) {
					addSimpleValue(cw, typeName, itemTag, nameStr, valueStr, "");
				}
				break;
			case "style":
				if (nameStr != null) {
					addSimpleValue(cw, typeName, itemTag, nameStr, "", valueStr);
				}
				break;
			case "plurals":
				String quantity = PLURALS_MAP.get(value.getNameRef());
				addSimpleValue(cw, typeName, itemTag, "quantity", quantity, valueStr);
				break;
			default:
				addSimpleValue(cw, typeName, itemTag, null, null, valueStr);
				break;
		}
	}

	private void addSimpleValue(ICodeWriter cw, String typeName, String itemTag, String attrName, String attrValue, String valueStr) {
		if (valueStr == null) {
			return;
		}
		if (valueStr.startsWith("res/")) {
			// remove duplicated resources.
			return;
		}
		cw.startLine();
		cw.add('<').add(itemTag);
		if (attrName != null && attrValue != null) {
			if (typeName.equals("attr")) {
				cw.add(' ').add("name=\"").add(attrName.replace("id.", "")).add("\" value=\"").add(attrValue).add('"');
			} else if (typeName.equals("style")) {
				cw.add(' ').add("name=\"").add(attrName.replace("attr.", "")).add('"');
			} else {
				cw.add(' ').add(attrName).add("=\"").add(attrValue).add('"');
			}
		}

		if (itemTag.equals("string") && valueStr.contains("%") && StringFormattedCheck.hasMultipleNonPositionalSubstitutions(valueStr)) {
			cw.add(" formatted=\"false\"");
		}

		if (valueStr.isEmpty()) {
			cw.add(" />");
		} else {
			cw.add('>');
			if (itemTag.equals("string") || (typeName.equals("array") && valueStr.charAt(0) != '@')) {
				cw.add(StringUtils.escapeResStrValue(valueStr));
			} else {
				cw.add(StringUtils.escapeResValue(valueStr));
			}
			cw.add("</").add(itemTag).add('>');
		}
	}

	private String getFileName(ResourceEntry ri) {
		StringBuilder sb = new StringBuilder();
		String qualifiers = ri.getConfig();
		sb.append("res/values");
		if (!qualifiers.isEmpty()) {
			sb.append(qualifiers);
		}
		sb.append('/');
		sb.append(ri.getTypeName());
		if (!ri.getTypeName().endsWith("s")) {
			sb.append('s');
		}
		sb.append(".xml");
		return sb.toString();
	}
}

